"""Optional manual desktop QA server. Generated bytes only; stop with Ctrl+C."""
import http.server
import json

from test_transfers import DATA, DIGEST, Fixture

if __name__ == "__main__":
    server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Fixture)
    server.chunk_delay = 0.15
    print(json.dumps({"url": f"http://127.0.0.1:{server.server_port}/slow", "sha256": DIGEST, "bytes": len(DATA)}), flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
